/*
  pingoscope — RECEIVER (CYD ESP32-32E / ST7789)
  Cardio-style scrolling ping graph + public IP / country / ASN header.
  Two ESP-NOW msg types; BOOT toggles raw debug. VPN egress change -> red header.
  Board: ESP32 Dev Module. Libs: Adafruit_GFX + Adafruit_ST7789 (attach manually).
*/
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>
#include <string.h>

#define TFT_CS 15
#define TFT_DC 2
#define TFT_RST -1
#define TFT_BL 21
Adafruit_ST7789 tft(TFT_CS, TFT_DC, TFT_RST);

#define LED_R 22
#define LED_G 16
#define LED_B 17
inline void ledOff(){ digitalWrite(LED_R,HIGH); digitalWrite(LED_G,HIGH); digitalWrite(LED_B,HIGH); }
inline void ledGreen(bool on){ digitalWrite(LED_G,on?LOW:HIGH); }
inline void ledRed(bool on){ digitalWrite(LED_R,on?LOW:HIGH); }

#define BTN 0
#define ESPNOW_CHANNEL 1
#define MSG_PROBE 1
#define MSG_NETINFO 2

typedef struct __attribute__((packed)) { uint8_t type; uint32_t seq; uint16_t rtt_ms; uint8_t status; } probe_t;
typedef struct __attribute__((packed)) { uint8_t type; char ip[16]; char country[4]; char asn[40]; } netinfo_t;

const char* statusLabel(uint8_t s){ switch(s){case 0:return "OK";case 1:return "PING TIMEOUT";case 2:return "NO IP";default:return "LINK DOWN";} }

// ---- graph geometry (landscape 320x240) ----
#define HDR_H   54
#define PLOT_X0 6
#define PLOT_Y0 (HDR_H+2)
#define PLOT_W  308
#define PLOT_H  (240 - PLOT_Y0 - 4)
#define PLOT_X1 (PLOT_X0 + PLOT_W)
#define PLOT_Y1 (PLOT_Y0 + PLOT_H)
#define HIST    PLOT_W

uint16_t rttHist[HIST];
uint8_t  stHist[HIST];
int head=0, histCount=0;

volatile bool newProbe=false, newNet=false;
probe_t  lastProbe = {MSG_PROBE,0,0,2};
netinfo_t lastNet;
char curIp[16]="", curCountry[4]="", curAsn[40]="", baseCountry[4]="";
bool egressChanged=false;

uint8_t lastMac[6];
int lastRssi=0;
uint32_t pktCount=0, missed=0, prevSeq=0;
bool haveSeq=false;
unsigned long lastRxMs=0, lastIntervalMs=0;

bool debugMode=false, forceRedraw=false;
unsigned long ledOffAt=0;

void handleRx(const uint8_t *mac, const uint8_t *data, int len){
  if (len<1) return;
  memcpy((void*)lastMac, mac, 6);
  unsigned long now=millis();
  if (data[0]==MSG_PROBE && len==(int)sizeof(probe_t)){
    memcpy(&lastProbe, data, sizeof(probe_t));
    lastIntervalMs = now-lastRxMs; pktCount++;
    if (haveSeq && lastProbe.seq>prevSeq+1) missed += (lastProbe.seq-prevSeq-1);
    prevSeq=lastProbe.seq; haveSeq=true; newProbe=true;
  } else if (data[0]==MSG_NETINFO && len==(int)sizeof(netinfo_t)){
    memcpy(&lastNet, data, sizeof(netinfo_t)); newNet=true;
  }
  lastRxMs=now;
}
#if ESP_ARDUINO_VERSION >= ESP_ARDUINO_VERSION_VAL(3,0,0)
void onRecv(const esp_now_recv_info_t *info, const uint8_t *data, int len){ lastRssi=info->rx_ctrl->rssi; handleRx(info->src_addr,data,len); }
#else
void onRecv(const uint8_t *mac, const uint8_t *data, int len){ lastRssi=0; handleRx(mac,data,len); }
#endif

String macStr(const uint8_t*m){ char b[18]; sprintf(b,"%02X:%02X:%02X:%02X:%02X:%02X",m[0],m[1],m[2],m[3],m[4],m[5]); return String(b); }

void pushSample(uint16_t rtt, uint8_t st){ rttHist[head]=rtt; stHist[head]=st; head=(head+1)%HIST; if(histCount<HIST)histCount++; }

void applyNet(){
  strncpy(curIp,lastNet.ip,sizeof(curIp)); curIp[sizeof(curIp)-1]=0;
  strncpy(curCountry,lastNet.country,sizeof(curCountry)); curCountry[sizeof(curCountry)-1]=0;
  strncpy(curAsn,lastNet.asn,sizeof(curAsn)); curAsn[sizeof(curAsn)-1]=0;
  if (baseCountry[0]==0 && curCountry[0]) strncpy(baseCountry,curCountry,sizeof(baseCountry));
  egressChanged = (baseCountry[0] && strcmp(baseCountry,curCountry)!=0);
}

void drawHeader(){
  tft.fillRect(0,0,320,HDR_H,ST77XX_BLACK);
  tft.setCursor(6,4);
  if (lastProbe.status==0){ tft.setTextSize(3); tft.setTextColor(ST77XX_GREEN); tft.print(lastProbe.rtt_ms); tft.setTextSize(2); tft.print(" ms"); }
  else { tft.setTextSize(2); tft.setTextColor(ST77XX_RED); tft.print(statusLabel(lastProbe.status)); }
  if (curCountry[0]){ tft.setTextSize(3); tft.setTextColor(egressChanged?ST77XX_RED:ST77XX_CYAN);
    int w=strlen(curCountry)*18; tft.setCursor(320-w-6,4); tft.print(curCountry); }
  tft.setTextSize(1); tft.setTextColor(ST77XX_WHITE); tft.setCursor(6,34);
  if (curIp[0]){ tft.print(curIp); tft.print("  "); tft.print(curAsn); } else tft.print("waiting for net info...");
  if (egressChanged){ tft.setTextColor(ST77XX_RED); tft.setCursor(6,44); tft.print("EGRESS CHANGED - VPN?"); }
}

void drawGraph(){
  tft.fillRect(PLOT_X0,PLOT_Y0,PLOT_W,PLOT_H,ST77XX_BLACK);
  tft.drawFastHLine(PLOT_X0,PLOT_Y1,PLOT_W,0x2104);
  if (histCount==0) return;
  uint16_t mx=10;
  for (int i=0;i<histCount;i++){ int idx=(head-1-i+HIST*2)%HIST; if(stHist[idx]==0 && rttHist[idx]>mx) mx=rttHist[idx]; }
  uint32_t yMax=(uint32_t)mx*12/10+1; if(yMax<10)yMax=10;
  tft.setTextSize(1); tft.setTextColor(0x8410); tft.setCursor(PLOT_X0+2,PLOT_Y0+1); tft.print(yMax); tft.print("ms");
  int prevX=-1,prevY=-1; bool prevValid=false;
  for (int i=0;i<histCount;i++){
    int idx=(head-1-i+HIST*2)%HIST; int x=PLOT_X1-1-i;
    if (x<PLOT_X0) break;
    if (stHist[idx]!=0){ tft.drawFastVLine(x,PLOT_Y0,PLOT_H,ST77XX_RED); prevValid=false; }
    else {
      int y=PLOT_Y1-(int)((uint32_t)rttHist[idx]*PLOT_H/yMax);
      if(y<PLOT_Y0)y=PLOT_Y0; if(y>PLOT_Y1)y=PLOT_Y1;
      if (prevValid && prevX>=PLOT_X0) tft.drawLine(x,y,prevX,prevY,ST77XX_GREEN); else tft.drawPixel(x,y,ST77XX_GREEN);
      prevX=x; prevY=y; prevValid=true;
    }
  }
}

void drawDebug(){
  tft.fillScreen(ST77XX_BLACK);
  tft.setTextColor(ST77XX_YELLOW); tft.setTextSize(2); tft.setCursor(6,6); tft.println("DEBUG / raw ESP-NOW");
  tft.setTextColor(ST77XX_WHITE); tft.setTextSize(1); int y=34;
  tft.setCursor(6,y); tft.print("from  "); tft.println(macStr(lastMac)); y+=12;
  tft.setCursor(6,y); tft.print("rssi  "); tft.print(lastRssi); tft.println(" dBm"); y+=12;
  tft.setCursor(6,y); tft.print("pkts  "); tft.print(pktCount); tft.print("  missed "); tft.println(missed); y+=12;
  tft.setCursor(6,y); tft.print("rate  "); tft.print(lastIntervalMs?1000.0/lastIntervalMs:0,2); tft.println(" /s"); y+=16;
  tft.setCursor(6,y); tft.print("PROBE seq "); tft.print(lastProbe.seq);
    tft.print(" rtt "); tft.print(lastProbe.rtt_ms); tft.print(" st "); tft.print(lastProbe.status);
    tft.print(" ("); tft.print(statusLabel(lastProbe.status)); tft.println(")"); y+=16;
  tft.setCursor(6,y); tft.print("ip  "); tft.println(curIp[0]?curIp:"-"); y+=12;
  tft.setCursor(6,y); tft.print("cc  "); tft.print(curCountry[0]?curCountry:"-");
    tft.print("  base "); tft.println(baseCountry[0]?baseCountry:"-"); y+=12;
  tft.setCursor(6,y); tft.print("as  "); tft.println(curAsn[0]?curAsn:"-"); y+=12;
  tft.setCursor(6,y); tft.print("egress "); tft.println(egressChanged?"CHANGED":"stable");
}

void showBanner(){
  tft.fillScreen(ST77XX_BLACK);
  tft.setTextColor(ST77XX_WHITE); tft.setTextSize(2); tft.setCursor(6,6); tft.println("pingoscope");
  tft.setTextSize(1); tft.setCursor(6,34); tft.print("MAC: "); tft.println(WiFi.macAddress());
  tft.setCursor(6,50); tft.print("channel "); tft.println(ESPNOW_CHANNEL);
  tft.setCursor(6,66); tft.println("waiting for packets...");
}

void setup(){
  Serial.begin(115200); delay(300);
  pinMode(LED_R,OUTPUT); pinMode(LED_G,OUTPUT); pinMode(LED_B,OUTPUT); ledOff();
  pinMode(BTN,INPUT_PULLUP);
  pinMode(TFT_BL,OUTPUT); digitalWrite(TFT_BL,HIGH);
  SPI.begin(14,12,13,15);
  tft.init(240,320); tft.setRotation(1);
  uint8_t madctl = ST77XX_MADCTL_MX|ST77XX_MADCTL_MY|ST77XX_MADCTL_MV|ST77XX_MADCTL_RGB; // 0xE0
  tft.sendCommand(ST77XX_MADCTL,&madctl,1);

  WiFi.mode(WIFI_STA); WiFi.disconnect();
  esp_wifi_set_channel(ESPNOW_CHANNEL, WIFI_SECOND_CHAN_NONE);
  Serial.print("Receiver MAC: "); Serial.println(WiFi.macAddress());
  if (esp_now_init()!=ESP_OK){ tft.fillScreen(ST77XX_RED); return; }
  esp_now_register_recv_cb(onRecv);
  showBanner();
}

void loop(){
  static unsigned long lastToggle=0;
  if (digitalRead(BTN)==LOW && millis()-lastToggle>250){ lastToggle=millis(); debugMode=!debugMode; forceRedraw=true; }

  if (forceRedraw){ forceRedraw=false; tft.fillScreen(ST77XX_BLACK);
    if (debugMode) drawDebug(); else { drawHeader(); drawGraph(); } }

  if (newProbe){ newProbe=false; pushSample(lastProbe.rtt_ms,lastProbe.status);
    if (debugMode) drawDebug(); else { drawHeader(); drawGraph(); }
    ledGreen(true); ledOffAt=millis()+80; }

  if (newNet){ newNet=false; applyNet(); if(!debugMode) drawHeader(); }

  if (ledOffAt && millis()>ledOffAt){ ledGreen(false); ledOffAt=0; }
  ledRed(lastRxMs && millis()-lastRxMs>5000);
}

